package com.mzmiyazxakii.spin.client;
import com.mzmiyazxakii.spin.*;import net.minecraft.client.gui.GuiGraphics;import net.minecraft.client.gui.screens.Screen;import net.minecraft.client.gui.components.Button;import net.minecraft.network.chat.Component;import net.minecraft.world.item.ItemStack;
public class SpinSkinScreen extends Screen{private final ItemStack held;public SpinSkinScreen(ItemStack s){super(Component.translatable("screen.spin.skins.title"));held=s;}@Override protected void init(){int x=width/2-105,y=height/2-34;addRenderableWidget(Button.builder(Component.translatable("screen.spin.skins.default").append(SpinSkinManager.get(held)==0?" ✓":""),b->select(0)).bounds(x,y,210,20).build());addRenderableWidget(Button.builder(Component.translatable("screen.spin.skins.wrecking_ball").append(SpinSkinManager.get(held)==1?" ✓":""),b->select(1)).bounds(x,y+25,210,20).build());addRenderableWidget(Button.builder(Component.translatable("gui.done"),b->onClose()).bounds(width/2-50,y+55,100,20).build());}private void select(int s){SpinSkinManager.apply(held,s);if(minecraft!=null&&minecraft.player!=null){for(ItemStack st:minecraft.player.getInventory().items)if(st.is(SpinMod.STEEL_BALL.get()))SpinSkinManager.apply(st,s);for(ItemStack st:minecraft.player.getInventory().offhand)if(st.is(SpinMod.STEEL_BALL.get()))SpinSkinManager.apply(st,s);}SpinSkinNetwork.sendSkin(s);onClose();}@Override public void render(GuiGraphics g,int mx,int my,float pt){renderBackground(g);super.render(g,mx,my,pt);g.drawCenteredString(font,title,width/2,height/2-60,0xFFFFFF);g.drawCenteredString(font,Component.translatable("screen.spin.skins.subtitle"),width/2,height/2-47,0xB8B8B8);}@Override public boolean isPauseScreen(){return false;}}